class Choice(ParamType):
    """The choice type allows a value to be checked against a fixed set
    of supported values. All of these values have to be strings.

    You should only pass a list or tuple of choices. Other iterables
    (like generators) may lead to surprising results.

    The resulting value will always be one of the originally passed choices
    regardless of ``case_sensitive`` or any ``ctx.token_normalize_func``
    being specified.

    See :ref:`choice-opts` for an example.

    :param case_sensitive: Set to false to make choices case
        insensitive. Defaults to true.
    :param aliases: Optional mapping of string aliases to exact members of
        ``choices``. The mapping is copied. Aliases use the same normalization
        as choices, but are not shown in help or shell completion. Conflicting
        normalized aliases raise :exc:`BadParameter` during conversion.
    """

    name = "choice"

    def __init__(
        self,
        choices: t.Sequence[str],
        case_sensitive: bool = True,
        aliases: t.Optional[t.Mapping[str, str]] = None,
    ) -> None:
        self.choices = choices
        self.case_sensitive = case_sensitive
        self.aliases: t.Dict[str, str] = {}

        if aliases is not None:
            if not isinstance(aliases, Mapping):
                raise ValueError("Aliases must be a mapping.")

            original_choices = {choice: choice for choice in choices}

            for alias, target in aliases.items():
                if not isinstance(alias, str) or not isinstance(target, str):
                    raise ValueError("Alias names and targets must be strings.")

                if target not in original_choices:
                    raise ValueError(f"Alias target {target!r} is not a choice.")

                self.aliases[alias] = original_choices[target]

    def to_info_dict(self) -> t.Dict[str, t.Any]:
        info_dict = super().to_info_dict()
        info_dict["choices"] = self.choices
        info_dict["case_sensitive"] = self.case_sensitive
        return info_dict

    def get_metavar(self, param: "Parameter") -> str:
        choices_str = "|".join(self.choices)

        # Use curly braces to indicate a required argument.
        if param.required and param.param_type_name == "argument":
            return f"{{{choices_str}}}"

        # Use square braces to indicate an option or optional argument.
        return f"[{choices_str}]"

    def get_missing_message(self, param: "Parameter") -> str:
        return _("Choose from:\n\t{choices}").format(choices=",\n\t".join(self.choices))

    def convert(
        self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
    ) -> t.Any:
        def normalize_token(value: str) -> str:
            if ctx is not None and ctx.token_normalize_func is not None:
                value = ctx.token_normalize_func(value)

            return value

        # Preserve the original value for error messages and the original
        # choices for return values. Keep aliases separate to detect conflicts
        # with every canonical choice, even if canonical names also collide.
        normed_value = normalize_token(value)

        if not self.case_sensitive:
            normed_value = normed_value.casefold()

        normed_aliases = {}

        for alias, target in self.aliases.items():
            normed_alias = normalize_token(alias)

            if not self.case_sensitive:
                normed_alias = normed_alias.casefold()

            if (
                normed_alias in normed_aliases
                and normed_aliases[normed_alias] != target
            ):
                self.fail(
                    _("Alias {alias!r} maps to multiple choices.").format(alias=alias),
                    param,
                    ctx,
                )

            normed_aliases[normed_alias] = target

        normed_choices = {}

        for choice, original in {choice: choice for choice in self.choices}.items():
            normed_choice = normalize_token(choice)
            alias_key = normed_choice if self.case_sensitive else normed_choice.casefold()

            if alias_key in normed_aliases and normed_aliases[alias_key] != original:
                self.fail(
                    _("Alias {alias!r} maps to multiple choices.").format(alias=alias_key),
                    param,
                    ctx,
                )

            normed_choices[normed_choice] = original

        # Keep the two normalization stages separate to preserve the existing
        # selection order when canonical names collide in both stages.
        if not self.case_sensitive:
            normed_choices = {
                normed_choice.casefold(): original
                for normed_choice, original in normed_choices.items()
            }

        normed_choices.update(normed_aliases)

        if normed_value in normed_choices:
            return normed_choices[normed_value]

        choices_str = ", ".join(map(repr, self.choices))
        self.fail(
            ngettext(
                "{value!r} is not {choice}.",
                "{value!r} is not one of {choices}.",
                len(self.choices),
            ).format(value=value, choice=choices_str, choices=choices_str),
            param,
            ctx,
        )

    def __repr__(self) -> str:
        return f"Choice({list(self.choices)})"

    def shell_complete(
        self, ctx: "Context", param: "Parameter", incomplete: str
